import fallback from "@/data/menu-fallback.json";
import type { MenuCategoryDto, MenuPayload } from "./menu";

/**
 * Break-glass menu (api-contract 2, architecture 2): used by the /menu page ONLY when both the database
 * and the cached copy are unavailable. The page must show "Prices may have changed, ask staff".
 * The snapshot is regenerated by `pnpm menu:export-fallback` (scripts/export-menu-fallback.ts, built from
 * src/lib/data/menu-fallback-export.ts; runbook engineering/ops/menu-fallback.md).
 *
 * This JSON is bundled into the browser (the /menu error boundary is a client component), so it holds public
 * menu data only: no private settings, order rules, stock numbers or image URLs.
 */
/**
 * 2.0.0: `tableOrdering` is deliberately NOT in the snapshot. The break-glass menu is used only when the database is
 * unreachable, and then table ordering cannot work anyway (api-contract 9.12: the menu hides ordering when /api/menu
 * fails). Readers treat it as "off".
 */
export type MenuFallbackSettings = Omit<MenuPayload["settings"], "tableOrdering">;
export type MenuFallback = {
  /** ISO time the snapshot was taken; null = never generated (the empty placeholder). */
  generatedAt: string | null;
  /** Same shape as `MenuCategory[]` in the contract. Images are stripped and sold-out flags reset (see export). */
  categories: MenuCategoryDto[];
  /** Public display settings at snapshot time (the `/api/menu` subset; announcement always null). Optional: older snapshots lack it. */
  settings?: MenuFallbackSettings;
  note?: string;
};

export function getFallbackMenu(): MenuFallback {
  return fallback as unknown as MenuFallback;
}
